"""Журнал m1: 20-летняя панель (мои шаги расчёта) — тот же формат, что у исследователей."""
import json, hashlib, pathlib, collections
HERE = pathlib.Path(__file__).resolve().parent
T = []; n = [0]
def add(kind, parents=(), **kw):
    n[0] += 1; i = f"m1-{n[0]:03d}"; T.append({"id": i, "kind": kind, "parents": list(parents), **kw}); return i
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()[:16]
R = HERE / "raw20"
f_p = add("open", title="BTS TranStats: Schedule P-5.2, 1990–2026 (выгрузка пользователя 20.10.2026)", url="https://www.transtats.bts.gov/",
          locator=f"raw20/p52.csv, sha256 {sha(R/'p52.csv')}", note="68 364 строк; 2026 неполный — не используется")
f_t = add("open", title="BTS TranStats: Schedule T-2, 1991–2026", url="https://www.transtats.bts.gov/", locator=f"raw20/t2.csv, sha256 {sha(R/'t2.csv')}")
f_b = add("open", title="BTS TranStats: Schedule B-43 Aircraft Inventory, 2006–2025", url="https://www.transtats.bts.gov/",
          locator=f"raw20/b43.csv, sha256 {sha(R/'b43.csv')}", note="149 137 строк: борт, год выпуска, код типа, статус")
pan = json.load(open(HERE / "panel.json"))
d1 = add("infer", [f_p, f_t], value=f"{len(pan['rows'])} строк перевозчик × тип × год",
         note="Те же правила, что m0-001…005: класс Z, компоновка 1, тысячи USD, код 699 → A321. Ключ перевозчика — AIRLINE_ID "
              "(UNIQUE_CARRIER переиспользуется: «OH» был Comair, теперь PSA). Пропущено кварталов: "
              + ", ".join(f"{k} — {v}" for k, v in pan["skipped"].items())
              + ". Нерасшифрованные — в основном типы 1990-х (DC-10, 747-100/200, L-1011, F100): для них нет B-43, они не нужны")
ag = json.load(open(HERE / "ages.json"))
d2 = add("infer", [f_b], value="средний возраст перевозчик × тип × год",
         note="Код типа в B-43 — код L_AIRCRAFT_TYPE с цифрой варианта (6141 = 614 «737-800» + 1): берутся первые три цифры. "
              "Где кода нет — по тексту модели с учётом производителя (иначе «777-300» читалось бы как A300 — так и было в первой версии, исправлено). "
              "737-8/737-9 без кода заказчика с годом выпуска ≥2017/2018 — MAX. Только борта в эксплуатации (OPERATING_STATUS = Y). "
              "Возраст = год отчёта − год выпуска. Итог: " + ", ".join(f"{k} {v}" for k, v in ag["how"].items()))
d2b = add("infer", [d2], value="сверка с 10-K: совпадает",
          note="2025: Southwest 737-700 305 бортов / 19,1 года, 737-8 300 / 2,7; United MAX8 123, MAX9 120; Delta A220-100 45, A220-300 36. "
               "Republic по 10-K: E170/175 311 бортов, 13,0 года (a4)")
ix = json.load(open(HERE / "index.json"))
e1 = add("extract", url="https://fred.stlouisfed.org/data/WPS5541", title="FRED: PPI Aircraft Repair and Maintenance (WPS5541)",
         locator="таблица наблюдений, июнь", quote="Index Apr 2009=100 … 2009-06-01 100.000 … 2025-06-01 160.225",
         value="индекс ТОиР ВС с 04.2009", note="получено через WebFetch (промежуточная модель), значения — в index.json")
e2 = add("extract", url="https://fred.stlouisfed.org/data/PCU488190488190", title="FRED: PPI Other Support Activities for Air Transportation",
         locator="июнь 2004–2025", quote="2006-06-01 111.600 … 2009-06-01 117.900", value="для сшивки 2006–2008")
e3 = add("extract", url="https://www.minneapolisfed.org/about-us/monetary-policy/inflation-calculator/consumer-price-index-1913-",
         title="Minneapolis Fed: CPI-U annual averages", quote="2006 201.6 … 2025 321.9", value="альтернативный дефлятор")
d3 = add("infer", [e1, e2, e3], value="основной — PPI ТОиР ВС, проверка — CPI-U",
         note="Индекс цен именно на ремонт и ТО воздушных судов ближе к тому, что дорожало, чем потребительская инфляция. "
              "2006→2025: PPI ×1,69, CPI-U ×1,60 — расхождение ~6%, итог посчитан с обоими (вкладка «Кривые»)")
cv = json.load(open(HERE / "curves_ppi.json"))
al = collections.defaultdict(list)
for k, v in cv["alloc"].items():
    aid_or_c, y = k.split("|"); al[(aid_or_c, v)].append(int(y))
car = {r["aid"]: r["carrier"] for r in pan["rows"]}
d4 = add("infer", [d1], value="распределено формулой — по годам",
         note="Правило m0-124 применено к каждому году: ≥3 типа, доли планера и накладных у всех типов в пределах 0,03, "
              "итог в пределах ×1,35 → строки года исключены; если ровные только доли — итог берётся, разбивка нет. Найдено: "
              + "; ".join(f"{car.get(a, a)} {min(ys)}–{max(ys)} ({'итог' if v == 'total' else 'доли'}, {len(ys)} г.)" for (a, v), ys in sorted(al.items(), key=lambda x: car.get(x[0][0], '')) ))
pol = json.load(open(HERE / "policy.json"))
a5ids = [json.loads(l)["id"] for l in open(HERE / "trace" / "a5.jsonl") if l.strip() and json.loads(l).get("kind") == "conclude"]
aq = json.load(open(HERE / "alloc_q.json"))
byq = collections.defaultdict(list)
for k, v in aq.items(): byq[(v["carrier"], v["basis"])].append(int(k.split("|")[1]))
NB = {"bh": "блок-часам", "asm": "кресло-милям", "dep": "вылетам", "mi": "милям"}
d4b = add("infer", [d4], carrier="AA", value="распределено пропорционально базе — поквартально",
    note="Вопрос пользователя «почему у American высокие ставки» вскрыл второй вид распределения, который правило m0-124 пропускало: "
         "у American с 2015 года прямой ТОиР на 1000 кресло-миль одинаков у всех типов (2019 — 11,8 USD у 14 типов из 15, 2025 — 17,1 у всех 10), "
         "доли труда, материалов и подряда тоже одинаковы. Это разнесение общих расходов по кресло-милям: ставка типа на блок-час тогда — "
         "кресла × скорость × общая ставка, о самом типе она ничего не говорит. Правило: в квартале ≥3 типов и у ≥75% из них ставка на одну базу "
         "(блок-час, кресло-миля, вылет, миля) в пределах ±3% — квартал распределён; год исключается, если так ≥2 кварталов. Найдено: "
         + "; ".join(f"{c} по {NB[b]} {', '.join(str(y) for y in sorted(ys))}" for (c, b), ys in sorted(byq.items())))
d5 = add("infer", [d4, d4b] + a5ids, value="исключения по учётной политике",
         note="; ".join(f"{c}: {', '.join(str(p['from'])+'–'+str(p['to'])+' '+p['why'] for p in v)}" for c, v in pol.items()))
d6 = add("infer", [d4, d5], value=", ".join(f"{k}: {v}" for k, v in cv["excluded"].items()),
         note="Итог отбора строк 2006–2025. Строки «двигатели < 15% прямых» — договоры за налёт, учтённые вне строки ТОиР, или обслуживание у материнской")
fe = json.load(open(HERE / "fe_ppi_direct.json"))
d7 = add("infer", [d6, d3, d2], value=f"σ = {fe['by_class']['sigma']:.3f}, наблюдений {fe['by_class']['n']}, эластичность по сектору {fe['by_class']['sector_elasticity']:.2f}",
         note="ln(прямой ТОиР на блок-час, USD 2025) = тип + перевозчик + f(возраст; класс) + e·ln(сектор). Вес — блок-часы. "
              "f — ступени по 2 года, 12–13 лет = 1. Перевозчик — отдельный эффект: так разный учёт и разные зарплаты не смешиваются с возрастом. "
              "Бутстрэп по перевозчикам (200 повторов) — интервалы формы. Чартерные и грузовые — вне модели")
fi = json.load(open(HERE / "final_ppi.json"))
d8 = add("conclude", [d7], value="жизненный цикл 0–25 лет к зрелому: " + ", ".join(f"{g} {v:.2f}" for g, v in fi["life"].items()),
         note="Узкофюзеляжные: 0,33 в первые два года, 0,61 к 4–5 годам, 0,85 к 6–7, зрелый уровень с 10 лет — почти точно кривая RAND (0,31 / 0,59 / 0,81). "
              "Среднее за 25 лет 0,86 зрелого. Широкофюзеляжные мягче (0,70 в начале, 0,97 за цикл). Региональные дорожают после 14 лет; "
              "данных после 20 лет нет — хвост держится на значении 20–21 года")
v1 = add("infer", [d7], value="независимая перепроверка: совпадает до последнего знака",
         note="Отдельный агент с нуля, без моих скриптов, пересчитал из сырых файлов AA A320 2019, WN 737-700 2008 и 2022, DL 757-200 2009: "
              "ТОиР на блок-час, блок-часы, возраст, индекс, приведение к зрелому, медианы и коэффициенты цикла — расхождение 0. "
              "Логических ошибок не нашёл. Замечание по существу: вес строки в блок-часах делал ставку типа ставкой крупнейшего "
              "перевозчика (у 737-700 Southwest — 86% часов: 719 взвешенно против 806 без весов)")
w1 = add("infer", [v1], value="каждый перевозчик весит одинаково",
         note="Ставка типа — для типичного эксплуатанта, а не для крупнейшего: вес строки = её доля в блок-часах своего перевозчика по этому типу. "
              "Для хорошо наблюдаемых типов итог сдвинулся на 2–10% (A320 1063→1136, 737-700 719→733). Сравнение поколений от весов зависит "
              "сильно (787-9/767-400: 2,45→0,70; A321neo/A321: 1,82→1,11) — это признак, что по новым типам данных мало и отношения — не коэффициент для расчёта")
add("infer", [d5, w1], value="строже по политике: ставки ±5%, A320 −8%",
    note="Проверка на устойчивость: дополнительно исключены перевозчики, чья политика выведена косвенно (AirTran, Virgin America, Comair, "
         "America West, Allegiant до 2016). Ставки хорошо наблюдаемых типов меняются в пределах ±5%, A320 — на −8% (больше всего влияли "
         "AirTran и Virgin America). Коэффициенты цикла не меняются (0,86 / 0,97 / 1,16). В итоге — основной вариант, со всеми подтверждёнными и косвенными")
ro = json.load(open(HERE / "runout.json"))
r1 = add("infer", [d2, d6], value="доживание: собственный парк ×" + f"{ro['effect']['доживание, собственные']:.2f}, арендованный ×{ro['effect']['доживание, в аренде']:.2f}",
    note=f"Уход типа из парка перевозчика определён по B-43: последний год, когда тип есть у перевозчика, если перевозчик отчитывается и дальше. "
         f"{ro['merged_skipped']} уходов из-за прекращения отчётности самого перевозчика (слияния) не считаются — там парк переходит под другой код. "
         f"Осталось {len(ro['exits'])} уходов, {ro['n_runout']} строк в окне 3 лет. Из {ro['tails_total']} бортов {ro['tails_later_other_us']} потом "
         f"появились у другого перевозчика США — продажа или передача, не только списание; для эффекта это не важно. Эффект в модели с типом, "
         f"перевозчиком, возрастом и сектором: " + "; ".join(f"{k} ×{v:.2f} [{ro['by_year_ci'][k][0]:.2f}–{ro['by_year_ci'][k][1]:.2f}]" for k, v in ro["by_year"].items())
         + ". Аренда: при возврате борт приводят в условия договора — экономия съедается. Решение пользователя: окно 3 года исключено")
r2 = add("conclude", [r1], value="влияние на ставки типов: в пределах ±5%, кроме 737-400 (−9%), A330-200 (+6%)",
    note="Медиана по перевозчикам устойчива: строки доживания — малая доля. MD-80 после исключения 681 USD/ч (было 710): его дешевизна — не доживание, "
         "а сам тип в старом возрасте (дешёвые JT8D и запчасти со списанных бортов, простая конструкция); в данных он есть только в 14–28 лет")
for p in fi["pairs"]:
    add("conclude", [w1], value=f"{p['new']}/{p['old']}: {p['ratio']:.2f}" + (f", в том же возрасте {p['ratio_same_age']:.2f}" if p["ratio_same_age"] else ""),
        note=f"новый тип: {p['new_n']} строк, перевозчики {', '.join(p['new_carriers'])}, возраст до {p['age_hi']:.1f} лет; предшественник в том же возрасте — {p['old_same_n']} строк")
with open(HERE / "trace" / "m1.jsonl", "w") as f:
    for t in T: f.write(json.dumps(t, ensure_ascii=False) + "\n")
print(len(T), "шагов")
